def apply_tax(price, rate=0.1):
    total = price * (1 + rate)
    return round(total, 2)

bill = apply_tax(50, rate=0.2)
print(bill)

from io import StringIO

try:
    quantity = int("12")
except ValueError as error:
    print(f"Invalid quantity: {error}")
else:
    print(quantity)

with StringIO("first line\nsecond line\n") as file:
    first_line = file.readline().strip()
print(first_line)

from math import sqrt

def distance_from_zero(value):
    return sqrt(value * value)

if __name__ == "__main__":
    print(distance_from_zero(5))
